from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
left_wheel = Motor(Port.A, Direction.COUNTERCLOCKWISE)
right_wheel = Motor(Port.E, Direction.CLOCKWISE)
robot = DriveBase(left_wheel, right_wheel, 88, 146)


# The main program starts here.
print('Hello, Techtonicbot!')
robot.straight(-500)
robot.turn(-60)
robot.straight(-500)
robot.turn(110)
robot.settings(straight_acceleration=105)
robot.straight(-130)
robot.straight(50)
robot.settings(straight_acceleration=400)
robot.turn(-105)
robot.straight(350)
